-- Leads da Thay (Maio-Junho/2026) importados da planilha enviada.
-- Gerado automaticamente — 164 leads.

do $$
declare
  v_vend_id bigint;
begin
  select id into v_vend_id from equipe where nome = 'Thay' limit 1;
  if v_vend_id is null then
    raise exception 'Vendedora Thay não encontrada na tabela equipe';
  end if;

end $$;

notify pgrst, 'reload schema';
